#include <stdio.h>
#include <string.h>

#define MAXSTRLEN 10

typedef char SString[MAXSTRLEN + 1]; /* 下标 0 单元存放串长 */

void StrAssign(SString s, const char *t) {
    int len = (int)strlen(t), i;

    if (len > MAXSTRLEN)
        len = MAXSTRLEN;
    for (i = 1; i <= len; i++)
        s[i] = t[i - 1];
    s[0] = (char)len;
}

int StrCompare(SString s, SString t) {
    int i;

    for (i = 1; i <= s[0] && i <= t[0]; i++)
        if (s[i] != t[i])
            return s[i] - t[i];
    return s[0] - t[0];
}

int main(void) {
    SString s, t;
    char a[100], b[100];
    int i, cmp;

    scanf("%99s %99s", a, b);
    StrAssign(s, a);
    StrAssign(t, b);
    printf("%d %d\n", (int)s[0], (int)t[0]);
    cmp = StrCompare(s, t);
    printf("%d\n", cmp > 0 ? 1 : (cmp < 0 ? -1 : 0));
    for (i = 1; i <= s[0]; i++)
        printf("%c", s[i]);
    for (i = 1; i <= t[0]; i++)
        printf("%c", t[i]);
    printf("\n");
    return 0;
}
