#include <stdio.h>
#include <string.h>

#define MAXSTRLEN 20

typedef char SString[MAXSTRLEN + 1];

void StrAssign(SString s, const char *t) {
    int len = (int)strlen(t), i;

    if (len > MAXSTRLEN)
        len = MAXSTRLEN;
    for (i = 1; i <= len; i++)
        s[i] = t[i - 1];
    s[0] = (char)len;
}

/* 取 s 中第 pos 个字符起、长度为 len 的子串放入 sub，合法返回 1 */
int SubString(SString sub, SString s, int pos, int len) {
    int i;

    if (pos < 1 || pos > s[0] || len < 0 || pos + len - 1 > s[0])
        return 0;
    for (i = 1; i <= len; i++)
        sub[i] = s[pos + i - 1];
    ;
    sub[0] = (char)len;
    ;
    return 1;
}

/* 连接 s 与 t 到 u，若结果超长则截断并返回 0，否则返回 1 */
int Concat(SString u, SString s, SString t) {
    int i, uncut = 1;

    for (i = 1; i <= s[0]; i++)
        u[i] = s[i];
    if (s[0] + t[0] > MAXSTRLEN) {
        for (i = 1; i <= MAXSTRLEN - s[0]; i++)
            u[s[0] + i] = t[i];
        u[0] = (char)MAXSTRLEN;
        uncut = 0;
    } else {
        for (i = 1; i <= t[0]; i++)
            u[s[0] + i] = t[i];
        u[0] = (char)(s[0] + t[0]);
    }
    return uncut;
}

int main(void) {
    SString s, t, sub, u;
    char a[100], b[100];
    int pos, len, i;

    scanf("%99s %99s %d %d", a, b, &pos, &len);
    StrAssign(s, a);
    StrAssign(t, b);
    if (SubString(sub, s, pos, len)) {
        for (i = 1; i <= sub[0]; i++)
            printf("%c", sub[i]);
        printf("\n");
    } else
        printf("error\n");
    Concat(u, s, t);
    for (i = 1; i <= u[0]; i++)
        printf("%c", u[i]);
    printf("\n");
    return 0;
}

