int Index_KMP(const char S[], const char T[], const int next[]) {
    int i = 1, j = 1, n = (int)strlen(S), m = (int)strlen(T);

    while (i <= n && j <= m) {
        if (j == 0 || S[i - 1] == T[j - 1]) {
            i++;
            j++;
        } else
            j = next[j];
    }
    if (j > m)
        return i - m;
    return 0;
}

