#include <stdio.h>

/* 计算 A[rows][cols] 中 A[i][j] 的地址；rm 为 1 表示行优先，0 表示列优先 */
long Address(long base, int rows, int cols, int size, int i, int j, int rm) {
    long offset;

    if (rm)
