#include <stdio.h>

#define N 5
#define M (N * (N + 1) / 2)

/* 把 N 阶上三角矩阵 A（含主对角线）按行优先压缩存入 B[0..M-1]，
   下三角的公共常量 c 存入 B[M] */
void Compress(int A[][N], int c, int B[]) {
    int i, j, k = 0;

    for (i = 0; i < N; i++)
        for (j = i; j < N; j++)
            B[k++] = A[i][j];
    B[k] = c;
}

/* 取上三角矩阵的第 i 行第 j 列元素，下标从 0 开始 */
int Get(const int B[], int c, int i, int j) {
    if (i > j)
        return c;
    return B[i * (N - 1) - i * (i - 1) / 2 + j];
}

int main(void) {
    int A[N][N], B[M + 1], c;
    int i, j;

    for (i = 0; i < N; i++)
        for (j = 0; j < N; j++)
            if (scanf("%d", &A[i][j]) != 1)
                return 1;
    if (scanf("%d", &c) != 1)
        return 1;
    Compress(A, c, B);
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++)
            printf("%d ", Get(B, c, i, j));
        printf("\n");
    }
    return 0;
}

