void FastTransposeSMatrix(const TSMatrix *M, TSMatrix *T) {
    int col, t, p, q;
    int num[MAXSIZE + 1], cpot[MAXSIZE + 1];

    T->mu = M->nu;
    T->nu = M->mu;
    T->tu = M->tu;
    if (T->tu == 0)
        return;
    for (col = 1; col <= M->nu; col++)
        num[col] = 0;
    for (t = 1; t <= M->tu; t++) {
        col = M->data[t].j;
        num[col]++;
    }
    cpot[1] = 1;
    for (col = 2; col <= M->nu; col++)
        cpot[col] = cpot[col - 1] + num[col - 1];
    for (p = 1; p <= M->tu; p++) {
        col = M->data[p].j;
        q = cpot[col];
        T->data[q].i = M->data[p].j;
        T->data[q].j = M->data[p].i;
        T->data[q].e = M->data[p].e;
        cpot[col]++;
    }
}

int main(void) {
    TSMatrix M, T;
    int k;

    CreateSMatrix(&M);
    FastTransposeSMatrix(&M, &T);
    printf("%d %d %d\n", T.mu, T.nu, T.tu);
    for (k = 1; k <= T.tu; k++)
        printf("%d %d %d\n", T.data[k].i, T.data[k].j, T.data[k].e);
    return 0;
}

problems.stem:
下列程序递归求广义表的深度（每行输入一个广义表，输出其深度）。写出程序的运行结果。
```
#include <stdio.h>

#define MAXLEN 100

/* s 是广义表的字符串形式，如 "(a,(b,c))"；pos 为当前扫描位置 */
int Depth(const char *s, int *pos) {
    int max = 0, d;

    (*pos)++; /* 跳过左括号 */
    while (s[*pos] != '\0' && s[*pos] != ')') {
        if (s[*pos] == '(') {
            d = Depth(s, pos); /* 递归求子表深度 */
            if (d > max)
                max = d;
        } else
            (*pos)++; /* 原子结点，深度记 0 */
        if (s[*pos] == ',')
            (*pos)++;
    }
    (*pos)++; /* 跳过右括号 */
    return max + 1;
}

int main(void) {
    char s[MAXLEN];
    int pos;

    while (scanf("%99s", s) == 1) {
        pos = 0;
        printf("%d\n", Depth(s, &pos));
    }
    return 0;
}
```
