```
ababc abc
```

程序：
```c
#include <stdio.h>
#include <string.h>
#define MAXS 100

/* BF 匹配：返回 t 在 s 中首次出现的起始下标（0 起），找不到返回 -1 */
static int bf(const char *s, const char *t, int *cmp)
{
    int i = 0, j = 0, n = (int)strlen(s), m = (int)strlen(t);
    *cmp = 0;
    if (m == 0) return 0;
    while (i < n && j < m) {
        (*cmp)++;
        if (s[i] == t[j]) { i++; j++; }
        else { i = i - j + 1; j = 0; }
    }
    return (j == m) ? i - m : -1;
}

int main(void)
{
    char s[MAXS], t[MAXS];
    int p, cmp;
    if (scanf("%s %s", s, t) != 2) { printf("输入有误\n"); return 0; }
    p = bf(s, t, &cmp);
    printf("匹配位置=%d 比较次数=%d\n", p, cmp);
    return 0;
}

```

