写出下列程序在给定输入下的运行结果（逐行抄写，空格与换行都要一致）。

输入：
```
hello world
```

程序：
```c
#include <stdio.h>
#define MAXS 100
static int sLen(const char *s) {
    int n = 0;
    while (s[n] != '\0') n++;
    return n;
}
static int sCmp(const char *a, const char *b) {
    int i = 0;
    while (a[i] != '\0' && b[i] != '\0') {
        if (a[i] != b[i]) return a[i] - b[i];
        i++;
    }
    return a[i] - b[i];
}
int main(void) {
    char a[MAXS], b[MAXS];
    scanf("%s %s", a, b);
    int la = sLen(a), lb = sLen(b), c = sCmp(a, b);
    printf("a=%d b=%d 比较=%d\n", la, lb, c);
    return 0;
}
```

