```
ababcababc abcab
```

程序：
```c
#include <stdio.h>
#include <string.h>
#define MAXS 100
static void getNext(const char *t, int next[]) {
    int i = 0, j = -1, m = strlen(t);
    next[0] = -1;
    while (i < m - 1) {
        if (j == -1 || t[i] == t[j]) { i++; j++; next[i] = j; }
        else j = next[j];
    }
}
static int kmp(const char *s, const char *t) {
    int next[MAXS], i = 0, j = 0, n = strlen(s), m = strlen(t);
    getNext(t, next);
    if (m == 0) return 0;
    while (i < n && j < m) {
        if (j == -1 || s[i] == t[j]) { i++; j++; }
        else j = next[j];
    }
    return (j == m) ? i - m : -1;
}
int main(void) {
    char s[MAXS], t[MAXS];
    scanf("%s %s", s, t);
    printf("首次匹配位置 = %d\n", kmp(s, t));
    return 0;
}
```

