写出下列程序在给定输入下的运行结果（逐行抄写，空格与换行都要一致）。

输入：
```
(a,(b,c),d)
```

程序：
```c
#include <stdio.h>
#include <string.h>
#define MAXS 100
static int depth(const char *s, int *i) {
    int maxd = 0, d = 0;
    while (s[*i] != '\0' && s[*i] != ')') {
        if (s[*i] == '(') { (*i)++; d = depth(s, i) + 1; }
        else if (s[*i] == ',') { (*i)++; d = 0; }
        else { (*i)++; d = 0; }
        if (d > maxd) maxd = d;
    }
    if (s[*i] == ')') (*i)++;
    return maxd;
}
int main(void) {
    char g[MAXS];
    scanf("%s", g);
    int i = 0;
    int dep = depth(g, &i);
    printf("深度 = %d\n", dep);
    return 0;
}
```

