#include <stdio.h>
#include <string.h>
#define MAXS 100
static int depth(const char *s, int *i) {
    int maxd = 0, d = 0;
    while (s[*i] != '\0' && s[*i] != ')') {
        if (s[*i] == '(') { (*i)++; d = depth(s, i) + 1; }
        else if (s[*i] == ',') { (*i)++; d = 0; }
        else { (*i)++; d = 0; }
        if (d > maxd) maxd = d;
    }
    if (s[*i] == ')') (*i)++;
    return maxd;
}
int main(void) {
    char g[MAXS];
    scanf("%s", g);
    int i = 0;
    int dep = depth(g, &i);
    printf("深度 = %d\n", dep);
    return 0;
}

