aaaab
```

程序：
```c
#include <stdio.h>
#include <string.h>
#define MAXS 100
static void getNextVal(const char *t, int next[]) {
    int i = 0, j = -1, m = strlen(t);
    next[0] = -1;
    while (i < m - 1) {
        if (j == -1 || t[i] == t[j]) {
            i++; j++;
            next[i] = (t[i] != t[j]) ? j : next[j];
        }
        else j = next[j];
    }
}
int main(void) {
    char t[MAXS];
    int next[MAXS], i, m;
    scanf("%s", t);
    m = strlen(t);
    getNextVal(t, next);
    for (i = 0; i < m; i++) printf("%d%s", next[i], (i == m - 1) ? "\n" : " ");
    return 0;
}
```

