```

程序：
```c
#include <stdio.h>
#define N 5
static int k(int i, int j) {
    if (i < j) { int t = i; i = j; j = t; }
    return i * (i + 1) / 2 + j;
}
int main(void) {
    int sa[N * (N + 1) / 2], i, j;
    for (i = 0; i < N; i++)
        for (j = 0; j <= i; j++)
            sa[k(i, j)] = i * 10 + j;
    scanf("%d %d", &i, &j);
    printf("a[%d][%d] = %d\n", i, j, sa[k(i, j)]);
    return 0;
}
