输入：
```
ababab ab
```

程序：
```c
#include <stdio.h>
#include <string.h>
#define MAXS 100
/* BF：统计 t 在 s 中出现的所有位置（允许重叠），返回次数 */
static int bfCount(const char *s, const char *t)
{
    int n = (int)strlen(s), m = (int)strlen(t);
    int i = 0, cnt = 0;
    if (m == 0) return 0;
    while (i <= n - m) {
        int j = 0;
        while (j < m && s[i + j] == t[j]) j++;
        if (j == m) cnt++;
        i++;
    }
    return cnt;
}
int main(void)
{
    char s[MAXS], t[MAXS];
    if (scanf("%s %s", s, t) != 2) { printf("输入有误\n"); return 0; }
    printf("出现次数 = %d\n", bfCount(s, t));
    return 0;
}

