写出下列程序在给定输入下的运行结果（逐行抄写，空格与换行都要一致）。

输入：
```
helloworld world
```

程序：
```c
#include <stdio.h>
#include <string.h>
#define MAXS 100
/* Index：返回 t 在 s 中首次出现的位置（1 起），找不到返回 0 */
static int strIndex(const char *s, const char *t)
{
    int n = (int)strlen(s), m = (int)strlen(t), i, j;
    if (m == 0) return 1;
    for (i = 0; i <= n - m; i++) {
        for (j = 0; j < m; j++)
            if (s[i + j] != t[j]) break;
        if (j == m) return i + 1;
    }
    return 0;
}
int main(void)
{
    char s[MAXS], t[MAXS];
    if (scanf("%s %s", s, t) != 2) { printf("输入有误\n"); return 0; }
    printf("首次出现位置 = %d\n", strIndex(s, t));
    return 0;
}

