输入：
```
2 1
```

程序：
```c
#include <stdio.h>
/* 对称矩阵按行优先压缩到下三角一维数组，返回 a[i][j] 的压缩下标 k（0 起） */
static int symLoc(int i, int j)
{
    if (i < j) { int t = i; i = j; j = t; } /* 利用对称性交换，使 i >= j */
    return i * (i + 1) / 2 + j;
}
int main(void)
{
    int i, j;
    if (scanf("%d %d", &i, &j) != 2) { printf("输入有误\n"); return 0; }
    printf("压缩下标 = %d\n", symLoc(i, j));
    return 0;
}

```

