写出下列程序在给定输入下的运行结果（逐行抄写，空格与换行都要一致）。

输入：
```
(a,(b,c),d)
```

程序：
```c
#include <stdio.h>
#include <string.h>
#define MAXS 100
/* 广义表（字符串表示，如 (a,(b,c),d)）的长度：第一层元素个数 */
static int glLength(const char *s, int *i)
{
    int cnt = 0;
    while (s[*i] != '\0' && s[*i] != ')') {
        if (s[*i] == '(') { (*i)++; glLength(s, i); cnt++; }
        else if (s[*i] == ',') { (*i)++; }
        else { (*i)++; cnt++; }
    }
    if (s[*i] == ')') (*i)++;
    return cnt;
}
int main(void)
{
    char s[MAXS];
    if (scanf("%s", s) != 1) { printf("输入有误\n"); return 0; }
    int i = 1; /* 跳过最外层左括号 */
    printf("长度 = %d\n", glLength(s, &i));
    return 0;
}

```

